export type TranslationDictionary = typeof translations;

type NestedKey<T> = T extends object
    ? { [K in keyof T]: `${K & string}${T[K] extends object ? `.${NestedKey<T[K]>}` : ''}` }[keyof T]
    : '';

type TranslationKeys = NestedKey<TranslationDictionary['en']>;

function getFrom(obj: any, path: string): string | undefined {
    if (!obj) return undefined;
    return path
        .split(".")
        .reduce<any>((acc, part) => (acc && acc[part] !== undefined ? acc[part] : undefined), obj);
}

export function getTranslation(lang: LanguageCode, path: string): string {
    // 1) Language‑specific overrides
    const override = overrideTranslations[lang];
    const fromOverride = getFrom(override, path);
    if (typeof fromOverride === "string" && fromOverride.trim() !== "") {
        return fromOverride;
    }

    // 2) Base dictionary for the active language (not all LanguageCodes have a translation entry)
    const fromLang = getFrom((translations as Partial<Record<LanguageCode, typeof translations.en>>)[lang], path);
    if (
        typeof fromLang === "string" &&
        fromLang.trim() !== "" &&
        fromLang !== "[]"
    ) {
        return fromLang;
    }

    // 3) Fallback to English
    const fallback = getFrom(translations.en, path);
    if (typeof fallback === "string" && fallback.trim() !== "") {
        return fallback;
    }

    // 4) Last‑resort: return the key itself
    return path;
}

export function getNestedTranslation(obj: any, path: string): string {
    const value = path.split('.').reduce((acc, part) => (acc && acc[part] !== undefined ? acc[part] : undefined), obj);

    // Treat empty placeholder values like [] or "" as missing
    if (typeof value === "string" && value.trim() !== "" && value !== "[]") {
        return value;
    }

    // Fallback to English if available
    try {
        // eslint-disable-next-line @typescript-eslint/no-use-before-define
        const fallback = path
            .split('.')
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            .reduce<any>((acc, part) => (acc && (acc as any)[part] !== undefined ? (acc as any)[part] : undefined), translations.en);

        if (typeof fallback === "string" && fallback.trim() !== "") {
            return fallback;
        }
    } catch {
        // ignore and fall through to returning the key
    }

    return path;
}
